//! `sermofur_core::recall` against the scenarios that the .NET `RecallService` answered on the
//! real `SqliteStore` (`rust/tests/golden/recall.json`, regenerated by `rust/tools/recall-oracle`
//! on Windows, since excerpts follow the culture of the machine): each scenario is replayed in a
//! new instance, and every answer is compared with the JSON text the oracle wrote, line breaks
//! as `\n`.
//!
//! The excerpt follows the table of `sermofur_core::collation`, generated from the oracle
//! (decision of John of 2026-11-06, option B restricted); the cases that depend on the
//! neighbours of a character are listed in [`CONTEXT_DEVIATIONS`]. The test fails on any other
//! difference, and on a listed case that no longer differs.

use std::collections::HashSet;
use std::path::PathBuf;
use std::time::Instant;

use rusqlite::Connection;
use serde_json::{Value, json};
use sermofur_core::format::DateTimeOffset;
use sermofur_core::memory::MemoryContext;
use sermofur_core::recall::{self, MAX_RESULTS};
use sermofur_core::records::*;
use sermofur_core::search;
use sermofur_core::store::Store;
use uuid::Uuid;

/// Questions whose excerpt depends on the neighbours of a character, which the per-scalar table
/// of `sermofur_core::collation` does not model (named deviation of `PARITY.md`):
/// `(scenario, question)`. In each, .NET finds the term later than the table.
const CONTEXT_DEVIATIONS: &[(&str, &str)] = &[
    // A: `и` + U+0306 contracts into `й`.
    ("collation", "кит ctx1"),
    // A: alef + U+0654 (hamza above) contracts into `أ`.
    ("collation", "باب ctx2"),
    // B and D: a Bengali consonant before a two-part vowel (spacing marks of its grapheme).
    ("collation", "ক\u{9c7} ctx3"),
    // B: a Thai preposed vowel reorders with its consonant.
    ("collation", "ก ctx4"),
    // D: a combining letter with a primary weight belongs to the grapheme of its base.
    ("collation", "ao ctx5"),
    // D: a prepended mark joins the grapheme that follows.
    ("collation", "ab ctx6"),
    // D: Hangul jamo L V T form one grapheme.
    ("collation", "가 ctx7"),
];

struct Scratch(PathBuf);

impl Drop for Scratch {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

fn instance(prefix: &str) -> (Scratch, PathBuf, Uuid) {
    let scratch = Scratch(
        std::env::temp_dir().join(format!("sermofur-{prefix}-{}", Uuid::new_v4().simple())),
    );
    std::fs::create_dir_all(scratch.0.join(".sermofur")).expect("marker");
    let id = Uuid::parse_str("11111111-2222-4333-8444-555555555555").expect("GUID");
    let database = scratch.0.join(".sermofur").join("memory.db");
    sermofur_core::schema::create_database(&database, id).expect("created");
    (scratch, database, id)
}

fn text(value: &Value) -> &str {
    value.as_str().expect("string")
}

fn guid(value: &Value) -> Uuid {
    Uuid::parse_str(text(value)).expect("GUID")
}

/// Source passages written by another connection, as `SourceService` does through `SaveSource`.
fn insert_passages(database: &PathBuf, id: Uuid, scope: &str, documents: &[(i32, String)]) {
    let mut raw = Connection::open(database).expect("raw");
    let transaction = raw.transaction().expect("transaction");
    search::insert(&transaction, id, scope, RecordKind::Source, documents).expect("inserted");
    transaction.commit().expect("committed");
}

/// An answer as the oracle recorded it: the JSON text, or the refusal.
fn answer<T: serde::Serialize>(result: sermofur_core::error::Result<T>) -> Value {
    match result {
        Ok(value) => Value::String(
            sermofur_core::json::to_string(&value)
                .expect("JSON")
                .replace("\r\n", "\n"),
        ),
        Err(error) => json!({
            "code": error.code,
            "message": error.message,
            "exitCode": error.exit_code,
        }),
    }
}

/// An answer with the excerpt of every result blanked: a context case may move the window of
/// the excerpt, never the rest of the answer.
fn without_excerpts(answer: &Value) -> Value {
    let Some(text) = answer.as_str() else {
        return answer.clone();
    };
    let mut value: Value = serde_json::from_str(text).expect("JSON answer");
    let results = match value.get_mut("results") {
        Some(results) => results,
        None => &mut value,
    };
    for result in results.as_array_mut().expect("results") {
        result["excerpt"] = Value::Null;
    }
    value
}

#[test]
fn recall_answers_like_the_dotnet_service() {
    let path = format!(
        "{}/../../tests/golden/recall.json",
        env!("CARGO_MANIFEST_DIR")
    );
    let golden: Value =
        serde_json::from_str(&std::fs::read_to_string(path).expect("golden file")).expect("JSON");
    let mut mismatches = Vec::new();
    let mut deviations = HashSet::new();
    let mut questions = 0;
    for scenario in golden["scenarios"].as_array().expect("scenarios") {
        let name = text(&scenario["name"]);
        let (scratch, database, id) = instance("recall");
        let mut store = Store::open(&scratch.0, id, false).expect("opened");
        for step in scenario["steps"].as_array().expect("steps") {
            match text(&step["op"]) {
                "addScope" => {
                    let kind = ScopeKind::NAMES
                        .iter()
                        .find(|(n, _, _)| *n == text(&step["kind"]))
                        .map(|(_, _, m)| *m)
                        .expect("scope kind");
                    let scope = Scope {
                        id: text(&step["id"]).to_owned(),
                        kind,
                        parent_id: Some(text(&step["parent"]).to_owned()),
                        relative_path: Some(text(&step["path"]).to_owned()),
                    };
                    store.add_scope(&scope, |_| Ok(())).expect("scope added");
                }
                "create" => {
                    let record: MemoryRecord =
                        read(text(&step["payload"]), &|_| 0).expect("payload");
                    store.create_record(&record, None).expect("created");
                }
                "invalidate" => {
                    store
                        .invalidate_record(
                            guid(&step["id"]),
                            text(&step["scope"]),
                            "Obsolète",
                            "john",
                        )
                        .expect("invalidated");
                }
                "insertPassages" => {
                    let documents: Vec<(i32, String)> = step["passages"]
                        .as_array()
                        .expect("passages")
                        .iter()
                        .map(|p| {
                            let passage = p[0].as_i64().expect("passage");
                            (i32::try_from(passage).expect("int"), text(&p[1]).to_owned())
                        })
                        .collect();
                    insert_passages(
                        &database,
                        guid(&step["id"]),
                        text(&step["scope"]),
                        &documents,
                    );
                }
                op @ ("recall" | "close") => {
                    questions += 1;
                    let context = MemoryContext {
                        root: scratch.0.clone(),
                        scope_id: text(&step["scope"]).to_owned(),
                        visible: HashSet::new(),
                    };
                    let query = text(&step["query"]);
                    let now = DateTimeOffset::now_utc();
                    let actual = if op == "recall" {
                        let limit =
                            i32::try_from(step["limit"].as_i64().expect("limit")).expect("int");
                        answer(recall::recall(&store, &context, query, limit, now))
                    } else {
                        let exclude = step["exclude"]
                            .as_str()
                            .map(|id| Uuid::parse_str(id).expect("GUID"));
                        answer(recall::close_claims(&store, &context, query, exclude, now))
                    };
                    let known = CONTEXT_DEVIATIONS.contains(&(name, query));
                    if actual != step["answer"] {
                        if known && without_excerpts(&actual) == without_excerpts(&step["answer"]) {
                            deviations.insert((name, query));
                        } else {
                            mismatches.push(format!(
                                "{name} {op} {query:?}:\n  expected {}\n  got      {}",
                                step["answer"], actual
                            ));
                        }
                    } else if known {
                        mismatches.push(format!(
                            "{name} {query:?}: listed in CONTEXT_DEVIATIONS but equal"
                        ));
                    }
                }
                other => panic!("unknown step {other}"),
            }
        }
    }
    eprintln!(
        "recall: {questions} questions compared, {} context deviations",
        deviations.len()
    );
    assert!(mismatches.is_empty(), "{}", mismatches.join("\n"));
}

/// Port of `RecallPerformanceTests.RecallStaysUnderTheReferenceBudgetOnALargeInstance` (SC-004):
/// 10,000 claims and RETEX (half of the claims with evidence, a quarter of it contradicting)
/// and 1,000 sources of 20 passages, then the p95 of 30 recalls, each on a newly opened store.
/// Run with `SERMOFUR_PERFORMANCE=1`, as the .NET measure; a fixed generator replaces
/// `System.Random`, so the data is alike, not identical.
#[test]
fn recall_stays_under_the_reference_budget_on_a_large_instance() {
    if std::env::var("SERMOFUR_PERFORMANCE").as_deref() != Ok("1") {
        eprintln!("performance measure skipped: set SERMOFUR_PERFORMANCE=1 to run it");
        return;
    }
    const VOCABULARY: [&str; 24] = [
        "cache",
        "déploiement",
        "postgres",
        "migration",
        "index",
        "latence",
        "réseau",
        "build",
        "pipeline",
        "certificat",
        "keycloak",
        "angular",
        "service",
        "requête",
        "journal",
        "sauvegarde",
        "restauration",
        "quota",
        "mémoire",
        "processus",
        "thread",
        "verrou",
        "transaction",
        "schéma",
    ];
    let mut state: u64 = 7;
    let mut next = |bound: u64| {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        usize::try_from(state % bound).expect("small")
    };
    let mut sentence = |words: usize| -> String {
        (0..words)
            .map(|_| {
                if next(4) == 0 {
                    VOCABULARY[next(24)].to_owned()
                } else {
                    format!("mot{}", next(5_000))
                }
            })
            .collect::<Vec<_>>()
            .join(" ")
    };
    let (scratch, database, id) = instance("recall-performance");
    let user = Provenance {
        origin: ActorKind::User,
        actor: Some("local-user".to_owned()),
        timestamp: DateTimeOffset::now_utc(),
    };
    let record = |kind, status, content: String| MemoryRecord {
        id: Uuid::new_v4(),
        scope_id: Some("workspace".to_owned()),
        kind,
        status,
        revision: 1,
        content_json: Some(content),
        provenance: Some(user.clone()),
    };
    let mut connection = Connection::open(&database).expect("raw");
    let transaction = connection.transaction().expect("transaction");
    let insert = |record: &MemoryRecord, path: Option<&str>, claim: Option<Uuid>| {
        transaction
            .execute(
                "INSERT INTO records(id,scope_id,kind,claim_id,payload,revision,source_path) VALUES(?1,'workspace',?2,?3,?4,1,?5)",
                rusqlite::params![
                    record.id.hyphenated().to_string(),
                    format!("{:?}", record.kind),
                    claim.map(|c| c.hyphenated().to_string()),
                    write(record).expect("JSON"),
                    path
                ],
            )
            .expect("inserted");
    };
    for index in 0..10_000 {
        let claim = index % 5 != 0;
        let text = sentence(12);
        let content = if claim {
            write(&ClaimContent {
                text: Some(text),
                category: MemoryCategory::Semantic,
                volatility: Volatility::Evolving,
                last_verified: None,
                review_after: None,
            })
        } else {
            write(&RetexContent {
                event: Some(text),
                impact: Some("impact".to_owned()),
                next_action: Some("next".to_owned()),
            })
        }
        .expect("JSON");
        let (kind, status) = if claim {
            (RecordKind::Claim, KnowledgeStatus::Proposed)
        } else {
            (RecordKind::Retex, KnowledgeStatus::Draft)
        };
        let created = record(kind, status, content);
        insert(&created, None, None);
        if claim && index % 2 == 1 {
            let relation = if index % 8 == 1 {
                EvidenceRelation::Contradicts
            } else {
                EvidenceRelation::Supports
            };
            let evidence = EvidenceContent {
                claim_id: created.id,
                kind: EvidenceKind::SourceCode,
                reference: Some("src/file.cs".to_owned()),
                lineage_id: Some(format!("origin{}", index % 50)),
                relation,
                source_id: None,
                source_hash: None,
            };
            let content = write(&evidence).expect("JSON");
            insert(
                &record(RecordKind::Evidence, KnowledgeStatus::Proposed, content),
                None,
                Some(created.id),
            );
        }
        search::insert(
            &transaction,
            created.id,
            "workspace",
            kind,
            &search::documents(&created).expect("documents"),
        )
        .expect("indexed");
    }
    for index in 0..1_000 {
        let passages: Vec<(i32, String)> = (0..20).map(|n| (n, sentence(140))).collect();
        let source = SourceContent {
            relative_path: Some(format!("docs/{index}.md")),
            status: SourceStatus::Indexed,
            hash: Some("hash".to_owned()),
            size: 20_000,
            indexed_at: Some(DateTimeOffset::now_utc()),
            passages: 20,
            rejection: None,
        };
        let created = record(
            RecordKind::Source,
            KnowledgeStatus::Active,
            write(&source).expect("JSON"),
        );
        insert(&created, source.relative_path.as_deref(), None);
        search::insert(
            &transaction,
            created.id,
            "workspace",
            RecordKind::Source,
            &passages,
        )
        .expect("indexed");
    }
    transaction.commit().expect("committed");
    drop(connection);

    let mut timings = Vec::new();
    for _ in 0..30 {
        let question = format!(
            "{} {} {}",
            VOCABULARY[next(24)],
            VOCABULARY[next(24)],
            VOCABULARY[next(24)]
        );
        let watch = Instant::now();
        let store = Store::open(&scratch.0, id, true).expect("opened");
        let context = MemoryContext {
            root: scratch.0.clone(),
            scope_id: "workspace".to_owned(),
            visible: HashSet::new(),
        };
        let answer = recall::recall(
            &store,
            &context,
            &question,
            MAX_RESULTS,
            DateTimeOffset::now_utc(),
        )
        .expect("recall");
        timings.push(watch.elapsed().as_secs_f64() * 1000.0);
        assert!((1..=3).contains(&answer.results.len()), "{question}");
    }
    timings.sort_by(f64::total_cmp);
    // `timings[(int)Math.Ceiling(30 * 0.95) - 1]`.
    let p95 = timings[28];
    eprintln!(
        "recall p50 {:.0} ms, p95 {p95:.0} ms, max {:.0} ms",
        timings[15], timings[29]
    );
    assert!(
        p95 < 1_000.0,
        "recall p95 {p95:.0} ms exceeds the 1 s ceiling of SC-004"
    );
}
